// Episode 02 timing (generated by scripts/build-timeline-ep02.mjs).
import timeline from '../data/ep02/timeline.json';
import narration from '../data/ep02/narration.json';
import durations from '../data/ep02/vo-durations.json';

export const FPS = timeline.fps;
export const TOTAL = timeline.total;
export const SCENES = timeline.scenes;
export type VoId = keyof typeof timeline.vo;
const DUR = durations as Record<string, number>;
const SAY = Object.fromEntries(narration.lines.map((l) => [l.id, l.say.replace(/[{}]/g, '')]));

export const scene = (id: number) => SCENES.find((s) => s.id === id)!;
export const vo = (id: VoId) => timeline.vo[id];
export const voEnd = (id: VoId) => timeline.vo[id] + Math.ceil(DUR[id] * FPS);
/** Local (scene) frame at which a line starts / a word is spoken. */
export const L = (sceneId: number, globalFrame: number) => globalFrame - scene(sceneId).from;
export const wordAt = (id: VoId, word: string) => {
  const s = SAY[id].toLowerCase();
  const i = s.indexOf(word.toLowerCase());
  return Math.round(vo(id) + (i < 0 ? 0 : i / s.length) * DUR[id] * FPS);
};
export const lw = (sceneId: number, id: VoId, word?: string) => L(sceneId, word ? wordAt(id, word) : vo(id));

export type Line = {id: string; scene: number; sub: string; from: number; to: number};
export const LINES: Line[] = narration.lines.map((l) => ({id: l.id, scene: l.scene, sub: l.sub, from: vo(l.id as VoId), to: voEnd(l.id as VoId)}));
